SourceCode.Declaration:
class FMVehicleListPageItem extends FMVehiclePage
{
    private str vehicleDescriptionInternal;
    private str vehicleVINInternal;
    private ImageReference vehicleImage;
    private FMVehicleStatus vehicleStatusInternal;

}

Method.Source:
[SysAppField(tableMethodStr(FMVehicle,FullDescription), "Vehicle description")]
public str vehicleDescription(str _value=vehicleDescriptionInternal)
{
    vehicleDescriptionInternal = _value;
    return vehicleDescriptionInternal;
}

[SysAppField(fieldStr(FMVehicle, VIN), "VIN")]
public str vehicleVIN(str _value=vehicleVINInternal)
{
    vehicleVINInternal = _value;
    return vehicleVINInternal;
}

[SysAppField(fieldStr(FMVehicle, Status), "Status")]
public FMVehicleStatus vehicleStatus(FMVehicleStatus _value=vehicleStatusInternal)
{
    vehicleStatusInternal = _value;
    return vehicleStatusInternal;
}

[SysAppField(fieldStr(FMVehicleModel,Image ), "Vehicle image")]
public ImageReference vehicleImage(ImageReference _value=vehicleImage)
{
    vehicleImage = _value;
    return vehicleImage;
}

public void populate(FMVehicle _vehicleTable, FMVehicleModel _vehicleModel = null)
{
    if (_vehicleModel)
    {
        if (_vehicleModel.Image != conNull())
        {
            Image img = new Image();
            img.setData(_vehicleModel.Image);
            this.vehicleImage(ImageReference::constructForImage(img));
        }
    }
    this.vehicleDescription(_vehicleTable.FullDescription());
    this.vehicleStatus(_vehicleTable.Status);
    this.RecId(_vehicleTable.RecId);

    this.vehicleVIN(_vehicleTable.VIN);
}
